bool Converter<content::Referrer>::FromV8(
    v8::Isolate* isolate,
    v8::Local<v8::Value> val,
    content::Referrer* out) {
  mate::Dictionary dict;
  if (!ConvertFromV8(isolate, val, &dict))
    return false;

  if (!dict.Get("url", &out->url))
    return false;

  if (!dict.Get("policy", &out->policy))
    return false;

  return true;
}

